function normalizePath(pathname: string) {
  return pathname.split('?')[0]?.replace(/\/$/, '') || '/angelcare-360-command-center'
}
function routePattern(route: string) {
  const escaped = route.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\\\[[^/]+\\\]/g, '[^/]+')
  return new RegExp(`^${escaped}/?$`)
}
export function getAngelcare360RouteBinding(pathname: string): ProductRouteBinding | null {
  const normalized = normalizePath(pathname)
  const exact = ANGELCARE360_ROUTE_BINDINGS.find((item) => item.route === normalized)
  if (exact) return exact
  return ANGELCARE360_ROUTE_BINDINGS.find((item) => item.route.includes('[') && routePattern(item.route).test(normalized)) || null
}
export function getAngelcare360ProductModule(moduleKey: string) {
  return ANGELCARE360_PRODUCT_MODULES.find((item) => item.key === moduleKey) || null
}
export function getAngelcare360ProductCapability(capabilityKey: string) {
  return ANGELCARE360_PRODUCT_CAPABILITIES.find((item) => item.key === capabilityKey) || null
}
